def read_account(account_id: int, request: Request):
    account = current(request)
    conn = request.app.state.conn
    row = conn.execute(
        "SELECT * FROM accounts WHERE id = ?", (account_id,)
    ).fetchone()
    if row is None:
        fail(404, "not found")
    if int(account["id"]) != int(account_id) and not access.may_read_account(conn, account["id"], account_id):
        fail(404, "not found")
    return account_json(row, include_recovery=int(account["id"]) == int(row["id"]))

def read_note(note_id: int, request: Request):
    account = current(request)
    conn = request.app.state.conn
    row = conn.execute(
        "SELECT * FROM notes WHERE id = ?", (note_id,)
    ).fetchone()
    if row is None or not access.may_read_account(conn, account["id"], row["account_id"]):
        fail(404, "not found")
    return note_json(row)

def update_device(device_id: int, body: DeviceUpdate, request: Request):
    account = current(request)
    label = body.label.strip()
    if not label:
        fail(400, "invalid device")
    conn = request.app.state.conn
    row = conn.execute(
        "SELECT * FROM devices WHERE id = ?", (device_id,)
    ).fetchone()
    if row is None:
        fail(404, "not found")
    if int(row["owner_account_id"]) != int(account["id"]):
        fail(403, "forbidden")
    conn.execute(
        "UPDATE devices SET label = ? WHERE id = ?", (label, device_id)
    )
    conn.commit()
